pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Use seed to derive an owner and fund the contract with some Ether.
        address owner = address(uint160(seed));
        vm.assume(owner != address(0));
        vm.deal(owner, 1 ether);
        // Fund contract
        vm.prank(owner);
        (bool ok,) = address(c).call{value: 1 ether}("");
        require(ok, "funding failed");
        // Owner calls sudicideAnyone
        vm.prank(owner);
        c.sudicideAnyone();
        // After the call, the contract's balance must be zero (ether was transferred to owner via selfdestruct)
        assertTrue(address(c).balance == 0);
    }
}

