pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        // owner must be the deployer of C, otherwise __onlyOwner fails
        vm.assume(owner == address(this));
        vm.prank(owner);
        c.sudicideAnyone();
        // After correct selfdestruct, any call to sudicideAnyone reverts because contract code is gone.
        // With the mutant (empty body), a second call succeeds.
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

