import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preBalance) public {
        address owner = address(0x1234);
        vm.deal(owner, preBalance + 1 ether);
        vm.prank(owner);
        c = new C();
        vm.deal(address(c), preBalance);
        uint256 balanceBefore = address(c).balance;
        vm.prank(owner);
        c.sudicideAnyone();
        uint256 size;
        address addr = address(c);
        assembly { size := extcodesize(addr) }
        if (size > 0) {
            assertEq(address(c).balance, balanceBefore);
        }
    }
}

