pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // bound the amount to something reasonable, but wide enough to find the bug
        vm.assume(amount > 0 && amount <= type(uint128).max);
        // deploy c fresh
        c = new C();
        // we need the owner to be a non-zero, non-address(0) address to observe the balance change
        address owner = address(0xb0b);
        vm.deal(owner, amount);
        vm.prank(owner);
        // fund the contract
        (bool ok, ) = payable(address(c)).call{value: amount}("");
        require(ok, "fund failed");
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;
        // call sudicideAnyone as owner
        vm.prank(owner);
        c.sudicideAnyone();
        // after selfdestruct, the contract code is gone, and funds move
        uint256 ownerBalanceAfter = owner.balance;
        // reference: owner gets contract balance, bug: owner gets nothing (funds go to address(0))
        // general rule: if owner != address(0) and contract had positive balance, owner's balance increases by contract's pre-destruct balance.
        // Bug: owner's balance does NOT increase by contract's pre-destruct balance.
        assertEq(ownerBalanceAfter - ownerBalanceBefore, contractBalanceBefore);
    }
}

