pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fundAmount, address owner) public {
        vm.assume(owner != address(0));
        vm.assume(fundAmount > 0);
        // Fund the contract so there is something to transfer on destruction
        vm.deal(address(c), fundAmount);
        // Record the owner’s balance before destruction
        uint256 ownerBalBefore = owner.balance;
        // The owner must be the actual owner of the contract, so set the owner to the fuzzed address.
        // The constructor sets __owner to msg.sender, which is the test contract here.
        // We need a mechanism to change the owner; however, C has no setter and inherits sGuardPlus with private __owner.
        // The only way to have a fuzzable owner is to deploy the contract with that owner.
        // Re-deploy with the fuzzed owner via vm.prank so __owner is set correctly.
        vm.prank(owner);
        c = new C();
        // Fund the newly deployed contract
        vm.deal(address(c), fundAmount);
        ownerBalBefore = owner.balance;
        uint256 contractBalBefore = address(c).balance;
        // Call sudicideAnyone as the owner
        vm.prank(owner);
        c.sudicideAnyone();
        // After destruction: address(c).code.length == 0 and owner should receive the funds
        uint256 ownerBalAfter = owner.balance;
        // The reference satisfies: owner balance increased exactly by the contract's balance before the call.
        // The buggy version sends to address(0) instead, so the owner’s balance increase is 0 (or less than contractBalBefore).
        assertTrue(ownerBalAfter == ownerBalBefore + contractBalBefore);
    }
}

