pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        uint256 gasBefore = gasleft();
        vm.prank(caller);
        try c.sudicideAnyone() {
            // The non-owner call should revert; if it does not, the property is violated.
            // In the buggy version, assert consumes all gas and does not revert,
            // so this branch is reachable, and the assertion fails.
            assertTrue(false, "call should have reverted");
        } catch {
            // Correct behavior: revert, gas not fully exhausted.
            uint256 gasAfter = gasleft();
            // The property: after the call reverts, remaining gas > 0 because revert does not consume all gas.
            // The buggy version exhausts all gas, leaving gasAfter = 0 (or near 0) on failure.
            assertTrue(gasAfter > 0, "gas was fully consumed");
        }
    }
}

