pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c));
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        vm.assume(caller != c.__owner());
        vm.startPrank(caller);
        uint256 gasBefore = gasleft();
        try c.sudicideAnyone() {
            // Success branch: should never happen according to the rule
            revert("unexpected success");
        } catch {
            // Revert branch: expected, gas must have been consumed by revert
        }
        uint256 gasAfter = gasleft();
        vm.stopPrank();
        // The rule: a revert from a non-owner must consume significantly less than the total forwarded gas.
        // The mutant's assert consumes all remaining gas, so gasAfter will be near 0.
        // We check that gasAfter is above a threshold, indicating a revert did not drain all gas.
        // The threshold is set as a fraction of gasBefore to account for varying initial gas.
        assertTrue(gasAfter > gasBefore / 2);
    }
}
